use forge_template :: Element ; use serde_json :: to_string_pretty ; use crate :: context :: ContextMessage ; use crate :: conversation :: Conversation ; use forge_test_kit :: json_fixture ; use super :: * ; # [doc = " Renders a conversation with related agent conversations in a single HTML"] # [doc = " document"] # [doc = ""] # [doc = " Creates a complete HTML page with the main conversation followed by"] # [doc = " related agent conversations. Uses anchor links for navigation."] # [doc = ""] # [doc = " # Arguments"] # [doc = ""] # [doc = " * `conversation` - The main conversation to render"] # [doc = " * `related` - Related agent conversations to include"] pub fn render_conversation_html_with_related (conversation : & Conversation , related : & [Conversation] ,) -> String { let c_title = format ! ("Title: {}" , conversation . title . clone () . unwrap_or (conversation . id . to_string ())) ; let mut body = Element :: new ("body") . append (create_info_table (conversation)) . append (create_conversation_context_section (conversation)) . append (create_tools_section (conversation)) ; if ! related . is_empty () { body = body . append (Element :: new ("div.section") . append (Element :: new ("h2") . text (format ! ("Related Agent Conversations ({})" , related . len ())) ,)) ; for related_conv in related { let anchor_id = format ! ("conversation-{}" , related_conv . id) ; body = body . append (Element :: new ("div.related-conversation") . attr ("id" , & anchor_id) . append (Element :: new ("div.back-to-main") . append (Element :: new ("a") . attr ("href" , "#") . text ("⬆ Back to main conversation") ,) ,) . append (create_info_table (related_conv)) . append (create_conversation_context_section (related_conv)) . append (create_tools_section (related_conv)) ,) ; } } let html = Element :: new ("html") . attr ("lang" , "en") . append (Element :: new ("head") . append (Element :: new ("meta") . attr ("charset" , "UTF-8")) . append (Element :: new ("meta") . attr ("name" , "viewport") . attr ("content" , "width=device-width, initial-scale=1.0") ,) . append (Element :: new ("title") . text (& c_title)) . append (Element :: new ("style") . text (include_str ! ("conversation_style.css"))) ,) . append (body) ; format ! ("<!DOCTYPE html>\n{}" , html . render ()) }